-- =========================================================================
-- 08_demo_data.sql: demo data for every table, one month and more of activity
-- Run order: 8 of 8, on a FRESH database (after files 01-07). Needs the client login columns (already in file 01).
-- Every row goes through the real procedures and triggers, so all business rules apply.
-- Dates are set with SET timestamp so the history looks real (Oct 2026 to Nov 2026).
-- Needs a MySQL user with the SESSION_VARIABLES_ADMIN privilege (an admin or root account has it).
-- All demo staff and client accounts use the password: admin123  (bcrypt hash). Change them for real use.
-- =========================================================================
USE rentacar;

DELIMITER $$
DROP PROCEDURE IF EXISTS demo_guard$$
CREATE PROCEDURE demo_guard()
BEGIN
  SET SESSION information_schema_stats_expiry = 0;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = DATABASE()
               AND ((table_name='address' AND AUTO_INCREMENT<>1) OR (table_name='branch' AND AUTO_INCREMENT<>1)
                 OR (table_name='client' AND AUTO_INCREMENT<>1) OR (table_name='car' AND AUTO_INCREMENT<>1)
                 OR (table_name='user' AND AUTO_INCREMENT<>2) OR (table_name='country' AND AUTO_INCREMENT<>1)
                 OR (table_name='reservation' AND AUTO_INCREMENT<>1))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Demo data must be loaded into a fresh database (files 01 to 07 only)';
  END IF;
END$$
DROP PROCEDURE IF EXISTS demo_pay_rest$$
CREATE PROCEDURE demo_pay_rest(IN p_res INT, IN p_method VARCHAR(20), IN p_ref VARCHAR(100), IN p_extra DECIMAL(10,2))
BEGIN
  DECLARE v_bal DECIMAL(12,2);
  DECLARE v_pid INT;
  SELECT balance INTO v_bal FROM view_reservationbalance WHERE reservationID = p_res;
  SET v_bal = v_bal + p_extra;
  IF v_bal > 0 THEN
    CALL sp_record_payment(p_res, 'Payment', v_bal, p_method, p_ref, v_pid);
  END IF;
END$$
DELIMITER ;
CALL demo_guard();

SET timestamp = UNIX_TIMESTAMP('2026-09-15 08:00:00');
SET @app_user_id = 1;

